PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('client','vendor','admin')), verified_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS auth_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, purpose TEXT NOT NULL CHECK(purpose IN ('verify','reset')), expires_at TEXT NOT NULL, consumed_at TEXT);
CREATE TABLE IF NOT EXISTS companies (id TEXT PRIMARY KEY, owner_user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('client','vendor')), company_name TEXT NOT NULL, contact_name TEXT NOT NULL, contact_email TEXT NOT NULL, phone TEXT, trade_license_no TEXT, license_expiry TEXT, categories TEXT NOT NULL DEFAULT '[]', emirate TEXT, verification_status TEXT NOT NULL DEFAULT 'pending', verified_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_companies_owner ON companies(owner_user_id);
CREATE TABLE IF NOT EXISTS agreement_versions (kind TEXT NOT NULL, version TEXT NOT NULL, agreement_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0, published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(kind,version));
CREATE TABLE IF NOT EXISTS agreement_acceptances (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), company_id TEXT REFERENCES companies(id), agreement_type TEXT NOT NULL, version TEXT NOT NULL, agreement_hash TEXT NOT NULL, accepted_at TEXT NOT NULL, ip_address TEXT, user_agent TEXT, service_charge_terms TEXT NOT NULL, UNIQUE(user_id,agreement_type,version));
CREATE TABLE IF NOT EXISTS public_requests (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL, location TEXT NOT NULL, category TEXT NOT NULL, title TEXT NOT NULL, scope TEXT NOT NULL, visit_requested INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'under_review', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_visits (id TEXT PRIMARY KEY, request_id TEXT NOT NULL UNIQUE REFERENCES public_requests(id), amount_fils INTEGER NOT NULL DEFAULT 10000 CHECK(amount_fils=10000), payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','pending_manual','paid','waived','refunded')), payment_reference TEXT, appointment_at TEXT, inspection_notes TEXT, measurements TEXT, rfq_id TEXT, status TEXT NOT NULL DEFAULT 'requested', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rfqs (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, client_company_id TEXT REFERENCES companies(id), public_request_id TEXT REFERENCES public_requests(id), title TEXT NOT NULL, category TEXT NOT NULL, sanitized_scope TEXT NOT NULL, original_scope TEXT NOT NULL, location_private TEXT, emirate TEXT, status TEXT NOT NULL DEFAULT 'under_review', closing_at TEXT, published_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_rfqs_client ON rfqs(client_company_id,status);
CREATE TABLE IF NOT EXISTS rfq_invitations (id TEXT PRIMARY KEY, rfq_id TEXT NOT NULL REFERENCES rfqs(id), vendor_company_id TEXT NOT NULL REFERENCES companies(id), status TEXT NOT NULL DEFAULT 'invited', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(rfq_id,vendor_company_id));
CREATE TABLE IF NOT EXISTS quotations (id TEXT PRIMARY KEY, rfq_id TEXT NOT NULL REFERENCES rfqs(id), vendor_company_id TEXT NOT NULL REFERENCES companies(id), amount_fils INTEGER NOT NULL CHECK(amount_fils>=0), currency TEXT NOT NULL DEFAULT 'AED', sanitized_notes TEXT, private_notes TEXT, labourer_count INTEGER, hours_per_labourer REAL, status TEXT NOT NULL DEFAULT 'submitted', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(rfq_id,vendor_company_id));
CREATE TABLE IF NOT EXISTS clarifications (id TEXT PRIMARY KEY, rfq_id TEXT NOT NULL REFERENCES rfqs(id), sender_user_id TEXT NOT NULL REFERENCES users(id), vendor_company_id TEXT REFERENCES companies(id), sanitized_message TEXT NOT NULL, private_message TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS awards (id TEXT PRIMARY KEY, rfq_id TEXT NOT NULL UNIQUE REFERENCES rfqs(id), quotation_id TEXT NOT NULL REFERENCES quotations(id), client_user_id TEXT NOT NULL REFERENCES users(id), vendor_company_id TEXT NOT NULL REFERENCES companies(id), awarded_amount_fils INTEGER NOT NULL, awarded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_charges (id TEXT PRIMARY KEY, award_id TEXT NOT NULL UNIQUE REFERENCES awards(id), basis TEXT NOT NULL, rate REAL NOT NULL, labourer_count INTEGER, hours_per_labourer REAL, amount_fils INTEGER NOT NULL CHECK(amount_fils>=0), status TEXT NOT NULL DEFAULT 'due', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, owner_kind TEXT NOT NULL, owner_id TEXT NOT NULL, uploaded_by TEXT REFERENCES users(id), storage_key TEXT NOT NULL UNIQUE, original_name TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, sanitized_key TEXT, review_status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS prospects (id TEXT PRIMARY KEY, name TEXT NOT NULL, domain TEXT, email TEXT, type TEXT NOT NULL CHECK(type IN ('client','vendor')), source_url TEXT, relevance TEXT, status TEXT NOT NULL DEFAULT 'review', opted_out INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(type,email));
CREATE TABLE IF NOT EXISTS email_log (id TEXT PRIMARY KEY, recipient TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, provider_id TEXT, error_code TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_email_daily ON email_log(created_at,status);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, next_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, actor_user_id TEXT REFERENCES users(id), entity_kind TEXT NOT NULL, entity_id TEXT, event TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
